begin;
create temporary table fixture_results(test text);
grant all on fixture_results to authenticated,anon;
create function pg_temp.fixture_denied(label text,statement text) returns void language plpgsql as $$ begin
 begin execute statement; exception when insufficient_privilege or invalid_parameter_value then insert into fixture_results values(label); return; end;
 raise exception 'Unexpected success: %',label;
end; $$;
grant execute on function pg_temp.fixture_denied(text,text) to authenticated,anon;
do $$ declare o uuid; s uuid; e uuid; t uuid; ids uuid[]:='{}'; i integer; u uuid:=gen_random_uuid(); begin
 insert into auth.users(id,email) values(u,'fixture-scorer-'||u||'@example.test');
 insert into public.organizations(name,slug) values('Texas fixture test','fixture-'||gen_random_uuid()) returning id into o;
 select id into s from public.sports where lower(name)='cricket' limit 1;
 insert into public.events(organization_id,sport_id,event_name,start_date,end_date,registration_type,status,pricing_model)
 values(o,s,'Frisco Fixture Test',current_date+30,current_date+31,'TEAM','REGISTRATION_CLOSED','FREE') returning id into e;
 insert into public.event_staff_assignments(event_id,user_id,staff_role) values(e,u,'SCORER');
 for i in 1..8 loop
  insert into public.teams(event_id,team_name,registration_status,approval_status) values(e,'Texas Team '||i,'APPROVED','APPROVED') returning id into t;
  insert into public.registrations(event_id,team_id,registration_type,registration_status,payment_status) values(e,t,'TEAM','APPROVED','NOT_REQUIRED');
  ids:=array_append(ids,t);
 end loop;
 perform set_config('test.fe',e::text,true);perform set_config('test.fu',u::text,true);
 perform set_config('test.fa',ids[1:4]::text,true);perform set_config('test.fb',ids[5:8]::text,true);
end; $$;
select set_config('request.jwt.claim.sub',current_setting('test.fu'),true);
set local role authenticated;
select pg_temp.fixture_denied('scorer cannot generate fixtures',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
select pg_temp.fixture_denied('private generator also checks permissions',format('select arenax_private.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true);
set local role authenticated;
select pg_temp.fixture_denied('null groups denied',format('select public.generate_cricket_fixtures(%L,null,null)',current_setting('test.fe')));
select pg_temp.fixture_denied('duplicate team groups denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fa')));
select pg_temp.fixture_denied('omitted approved team denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),((current_setting('test.fb')::uuid[])[1:3])::text));
select pg_temp.fixture_denied('unbalanced groups denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),((current_setting('test.fa')::uuid[])[1:2])::text,current_setting('test.fb')));
select pg_temp.fixture_denied('foreign or unknown team denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),(array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()])::text));
reset role;
update public.events set status='REGISTRATION_OPEN' where id=current_setting('test.fe')::uuid;
set local role authenticated;
select pg_temp.fixture_denied('open registration blocks generation',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
update public.events set status='REGISTRATION_CLOSED' where id=current_setting('test.fe')::uuid;
do $$ declare s uuid; begin select id into s from public.sports where name='Volleyball'; if s is null then insert into public.sports(name,participation_type) values('Volleyball','TEAM') returning id into s; end if; update public.events set sport_id=s where id=current_setting('test.fe')::uuid; end; $$;
set local role authenticated;
select pg_temp.fixture_denied('non-cricket generation denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
update public.events set sport_id=(select id from public.sports where lower(name)='cricket' limit 1) where id=current_setting('test.fe')::uuid;
insert into public.divisions(event_id,name) values(current_setting('test.fe')::uuid,'Existing manual bracket');
set local role authenticated;
select pg_temp.fixture_denied('existing manual competition preserved',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
delete from public.divisions where event_id=current_setting('test.fe')::uuid;
update public.registrations set registration_status='REJECTED' where team_id=(current_setting('test.fa')::uuid[])[1];
set local role authenticated;
select pg_temp.fixture_denied('unapproved registration denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
update public.registrations set registration_status='APPROVED' where team_id=(current_setting('test.fa')::uuid[])[1];
set local role authenticated;
do $$ declare n integer; begin
 n:=public.generate_cricket_fixtures(current_setting('test.fe')::uuid,current_setting('test.fa')::uuid[],current_setting('test.fb')::uuid[]);
 if n<>15 or (select count(*) from public.matches where event_id=current_setting('test.fe')::uuid)<>15 then raise exception 'Wrong match count'; end if;
 insert into fixture_results values('eight teams generate twelve group fixtures and three knockouts');
 if (select count(*) from public.standings s join public.groups g on g.id=s.group_id join public.divisions d on d.id=g.division_id where d.event_id=current_setting('test.fe')::uuid)<>8 then raise exception 'Missing standings'; end if;
 insert into fixture_results values('standings initialized for every team');
 if (select count(distinct least(home_team_id,away_team_id)::text||greatest(home_team_id,away_team_id)::text) from public.matches where event_id=current_setting('test.fe')::uuid and stage='GROUP')<>12 then raise exception 'Duplicate pair'; end if;
 insert into fixture_results values('each group pairing occurs exactly once');
 if exists(select 1 from public.matches where event_id=current_setting('test.fe')::uuid and (scheduled_start is not null or status<>'DRAFT' or result_status<>'PENDING')) then raise exception 'Unexpected published state'; end if;
 insert into fixture_results values('fixtures remain unscheduled pending drafts');
 if public.generate_cricket_fixtures(current_setting('test.fe')::uuid,current_setting('test.fa')::uuid[],current_setting('test.fb')::uuid[])<>15 or (select count(*) from public.matches where event_id=current_setting('test.fe')::uuid)<>15 then raise exception 'Retry duplicated fixtures'; end if;
 insert into fixture_results values('identical retry returns existing setup without duplicates');
end; $$;
select pg_temp.fixture_denied('changed groups cannot replace setup',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fb'),current_setting('test.fa')));
select pg_temp.fixture_denied('direct group composition changes denied','update public.group_members set seed_number=99');
select pg_temp.fixture_denied('setup audit is private','select * from arenax_private.cricket_fixture_setups');
select public.tournament_control(current_setting('test.fe')::uuid,'start');
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.fu'),true);
set local role authenticated;
do $$ declare m record; begin for m in select id from public.matches where event_id=current_setting('test.fe')::uuid and stage='GROUP' order by match_number loop perform public.record_cricket_result(m.id,90,4,48,80,6,48); end loop; end; $$;
reset role;
select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true);
set local role authenticated;
select public.resolve_semifinalists(current_setting('test.fe')::uuid);
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.fu'),true);
set local role authenticated;
do $$ declare m record; begin for m in select id from public.matches where event_id=current_setting('test.fe')::uuid and stage='SEMIFINAL' order by match_number loop perform public.record_cricket_result(m.id,90,4,48,80,6,48); end loop; end; $$;
select public.record_cricket_result((select id from public.matches where event_id=current_setting('test.fe')::uuid and stage='FINAL'),90,4,48,80,6,48);
reset role;
select set_config('request.jwt.claim.sub','3514e1cc-fca6-478b-a760-cb83eefac27e',true);
set local role authenticated;
select public.complete_tournament(current_setting('test.fe')::uuid);
do $$ begin if (select status from public.events where id=current_setting('test.fe')::uuid)<>'COMPLETED' then raise exception 'Generated bracket failed completion'; end if; insert into fixture_results values('generated fixtures work end-to-end through champion and completion'); end; $$;
select pg_temp.fixture_denied('completed event cannot regenerate',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
set local role anon;
select pg_temp.fixture_denied('anonymous generation denied',format('select public.generate_cricket_fixtures(%L,%L,%L)',current_setting('test.fe'),current_setting('test.fa'),current_setting('test.fb')));
reset role;
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(test order by test)) as verification from fixture_results;
rollback;
